import { tags } from "typia";

/**
 * Aggregated summary statistics of all product reviews across the platform, including total counts by deletion state and overall average rating. Used in the admin dashboard to monitor review health without exposing individual review content for privacy and compliance.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallReviewSnapshot = {
  /**
   * Total number of active, non-deleted product reviews across the platform.
   *
   * @x-autobe-specification Computes count of reviews where no snapshot has isDeleted=true. Uses: SELECT COUNT(DISTINCT review_id) FROM shopping_mall_review_snapshots WHERE review_id NOT IN (SELECT review_id FROM shopping_mall_review_snapshots WHERE deletedBy IS NOT NULL).
   */
  totalNonDeletedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of product reviews deleted by customers themselves, preserved in system for audit but excluded from public aggregations.
   *
   * @x-autobe-specification Computes count of reviews where at least one snapshot has deletedBy='user'. Uses: SELECT COUNT(DISTINCT review_id) FROM shopping_mall_review_snapshots WHERE deletedBy = 'user'; aggregates unique reviews that were deleted by users.
   */
  totalUserDeletedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of product reviews deleted by administrators due to policy violations. These are permanently removed from public view but retained in database with snapshot.
   *
   * @x-autobe-specification Computes count of reviews where at least one snapshot has deletedBy='admin'. Uses: SELECT COUNT(DISTINCT review_id) FROM shopping_mall_review_snapshots WHERE deletedBy = 'admin'; aggregates unique reviews that were deleted by administrators.
   */
  totalAdminDeletedCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Average customer rating across all active reviews, rounded to one decimal place (e.g., 4.2). Reflects overall product satisfaction without influence from deleted reviews.
   *
   * @x-autobe-specification Computes AVG of the rating field from the latest non-deleted snapshot for each review. Uses: SELECT AVG(s.rating) FROM (SELECT review_id, rating, ROW_NUMBER() OVER(PARTITION BY review_id ORDER BY createdAt DESC) as rn FROM shopping_mall_review_snapshots WHERE deletedBy IS NULL) s WHERE rn = 1;
   */
  averageRating: number &
    tags.Minimum<0> &
    tags.Maximum<5> &
    tags.MultipleOf<0.1>;
};
